    [3450]={name="Faerleia's Shield",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Pyrewood Ambush' - pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Pyrewood Ambush",lore="You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."},
