    [3758]={name="Crusader Belt",quality=2,ilvl=33,sourceType="quest_reward",instructions="Reward from the quest 'Syndicate Assassins' - pick it over the other choices. In Alterac Mountains.",zone="Alterac Mountains",questName="Syndicate Assassins",lore="I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate."},
