    [7326]={name="Thun'grim's Axe",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Forged Steel' - pick it over the other choices.",questName="Forged Steel",lore="I will give you a weapon, but first you must aid me. The Razormanes to the northwest came into my camp a few nights past."},
