    [11849]={name="Rustmetal Bracers",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Scavenging Deathknell' - pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Scavenging Deathknell",lore="You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."},
    [11852]={name="Roamer's Leggings",quality=1,ilvl=5,sourceType="quest_reward",instructions="Reward from the quest 'Rattling the Rattlecages' - pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Rattling the Rattlecages",lore="You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."},
    [11858]={name="Battlehard Cape",quality=2,ilvl=45,sourceType="quest_reward",instructions="Reward from the quest 'A Grim Discovery' - pick it over the other choices. In Feralas.",zone="Feralas",questName="A Grim Discovery",lore="What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."},
    [11862]={name="White Bone Band",quality=2,ilvl=52,sourceType="quest_reward",instructions="Reward from the quest 'Bone-Bladed Weapons' - pick it over the other choices. In Orgrimmar.",zone="Orgrimmar",questName="Bone-Bladed Weapons",lore="In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."},
