    [19019]={name="Thunderfury, Blessed Blade of the Windseeker",quality=5,ilvl=80,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Rise, Thunderfury!'.",questName="Rise, Thunderfury!",lore="Forged for a Windseeker of the elemental lords and lost for an age. Waking it again takes the bindings of the left and right hand, the blessing of Thunderaan's own essence, and a smith willing to defy Ragnaros.",proc="Chance on hit: Blasts your enemy with lightning, dealing 300 Nature damage and then jumping to additional nearby enemies.  Each jump reduces that victim's Nature resistance by 25. "},
