    [21674]={name="Gauntlets of Steadfast Determination",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Battleguard Sartura in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
