    [21688]={name="Boots of the Fallen Hero",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Vem in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Vem",lore="The third of the qiraji council, who charges the moment the fight begins and does not stop."},
    [21692]={name="Triad Girdle",quality=4,ilvl=75,reqLevel=60,sourceType="boss_drop",instructions="Drops from Lord Kri in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Lord Kri",lore="One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."},
    [21701]={name="Cloak of Concentrated Hatred",quality=4,ilvl=73,reqLevel=60,sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21710]={name="Cloak of the Fallen God",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Savior of Kalimdor' - pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [21814]={name="Breastplate of Annihilation",quality=4,ilvl=73,reqLevel=60,sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21995]={name="Boots of Heroism",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Anthion's Parting Words'. In Ironforge.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [21997]={name="Breastplate of Heroism",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [21998]={name="Gauntlets of Heroism",quality=4,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Just Compensation'. In Ironforge.",zone="Ironforge",questName="Just Compensation",lore="I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."},
    [21999]={name="Helm of Heroism",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Saving the Best for Last'. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22150]={name="Beads of Ogre Might",quality=3,ilvl=63,sourceType="quest_reward",instructions="Reward from the quest 'Falrin's Vendetta' - pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
