    [22659]={name="Medallion of the Dawn",quality=4,ilvl=60,sourceType="quest_reward",instructions="Reward from the quest 'Epic Armaments of Battle - Friend of the Dawn' - pick it over the other choices. In Eastern Plaguelands.",zone="Eastern Plaguelands",questName="Epic Armaments of Battle - Friend of the Dawn",lore="Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"},
    [22732]={name="Mark of C'Thun",quality=4,ilvl=88,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [22798]={name="Might of Menethil",quality=4,ilvl=89,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Menethil was the royal line of Lordaeron -- King Terenas, and his son Arthas, who became the Lich King. A warhammer carrying that name, guarded by the lich who served Arthas, is not an accident."},
    [22802]={name="Kingsfall",quality=4,ilvl=89,reqLevel=60,sourceType="boss_drop",instructions="Drops from Kel'Thuzad in Naxxramas.",zone="Naxxramas",npc="Kel'Thuzad",lore="Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."},
    [22808]={name="The Castigator",quality=4,ilvl=83,reqLevel=60,sourceType="boss_drop",instructions="Drops from Thaddius in Naxxramas.",zone="Naxxramas",npc="Thaddius",lore="Two abominations sewn into one and animated with stolen lightning -- one of Kel'Thuzad's more ambitious experiments in the Construct Quarter."},
